import { motion } from 'framer-motion';
import { ExternalLink } from 'lucide-react';
import { Link } from 'react-router-dom';

import { Project } from '../../types/common';
import { optimizeImageUrl } from '../../utils/imageUrl';
import { scrollToTop } from '../../utils/scroll';

interface ProjectCardProps {
  project: Project;
}

export default function ProjectCard({ project }: ProjectCardProps) {
  const formattedDate = project.date
    ? new Date(project.date).toLocaleDateString('en-US', {
        year: 'numeric',
        month: 'long',
      })
    : null;

  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      exit={{ opacity: 0, y: -20 }}
      className="group bg-white dark:bg-neutral-dark rounded-xl overflow-hidden shadow-lg hover:shadow-xl transition-all h-[24rem]"
    >
      <Link
        to={`/projects/${project.id}`}
        className="flex flex-col h-full"
        onClick={scrollToTop}
        aria-label={`View project details: ${project.title} - Client: ${project.client}${formattedDate ? ` - ${formattedDate}` : ''}`}
      >
        <div className="relative aspect-video overflow-hidden">
          {project.image && (
            <img
              src={optimizeImageUrl(project.image, 800)}
              alt={project.title}
              className="w-full h-full object-cover transform group-hover:scale-110 transition-transform duration-500"
              width={800}
              height={450}
              loading="lazy"
              decoding="async"
            />
          )}
          <div className="absolute inset-0 bg-gradient-to-t from-black/50 to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-300" />
          <div className="absolute bottom-4 right-4 bg-white dark:bg-neutral-dark rounded-full p-2 opacity-0 group-hover:opacity-100 transform group-hover:translate-y-0 translate-y-4 transition-all duration-300">
            <ExternalLink
              className="w-5 h-5 text-primary dark:text-primary-light"
              aria-hidden="true"
            />
          </div>
        </div>

        <div className="flex-1 p-6 flex flex-col">
          <div className="mb-2">
            <span className="text-sm font-medium text-primary dark:text-primary-light">
              {project.client}
            </span>
            {formattedDate && (
              <time
                dateTime={project.date}
                className="ml-2 text-sm text-neutral-dark/70 dark:text-white/70"
              >
                {formattedDate}
              </time>
            )}
          </div>

          <div className="flex-1 flex flex-col">
            <h3 className="text-xl font-bold text-neutral-dark dark:text-white mb-2 group-hover:text-primary dark:group-hover:text-primary-light transition-colors line-clamp-2">
              {project.title}
            </h3>

            <p className="text-neutral-dark/70 dark:text-white/70 line-clamp-3">
              {project.headline || project.description}
            </p>
          </div>
        </div>
      </Link>
    </motion.div>
  );
}
